<?php require 'config/database.php';require 'config/app.php';if(!isset($_SESSION['player_id']))go('login.php');$id=(int)($_GET['id']??$_POST['id']??0);$s=$pdo->prepare("SELECT r.*,t.name AS tournament_name,p.payment_id,p.amount,p.status AS pay_status FROM registrations r JOIN tournaments t ON t.tournament_id=r.tournament_id JOIN payments p ON p.registration_id=r.registration_id WHERE r.registration_id=? AND r.player_id=?");$s->execute([$id,(int)$_SESSION['player_id']]);$r=$s->fetch();if(!$r)go('dashboard.php');if((float)$r['amount']<=0)go('entry.php?id='.$id);if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$ref=trim($_POST['reference']??'');if(strlen($ref)<6){flash('warning','Enter a transaction reference at least 6 characters long.');go('payment.php?id='.$id);}try{$pdo->prepare("UPDATE payments SET transaction_reference=?,status='payment_review' WHERE registration_id=? AND status IN ('created','payment_review')")->execute([$ref,$id]);$pdo->prepare("UPDATE registrations SET status='payment_review' WHERE registration_id=? AND status='pending_payment'")->execute([$id]);flash('success','Reference submitted for administrator review.');go('entry.php?id='.$id);}catch(PDOException $e){flash('danger','This transaction reference may already be used.');go('payment.php?id='.$id);}}$pageTitle='Secure your slot';$upi='upi://pay?pa=rawaljnp%40okhdfcbank&pn=BGMI%20Esports%20Arena&am='.rawurlencode(number_format((float)$r['amount'],2,'.','')).'&cu=INR&tn='.rawurlencode($r['registration_code']);require 'includes/header.php';?>
<section class="page-hero compact"><div class="eyebrow">CHECKOUT / <?=e($r['registration_code'])?></div><h1>SECURE YOUR <span>SLOT.</span></h1><p>Scan to pay the exact entry fee for this tournament.</p></section><div class="payment-layout section"><section class="box"><div class="eyebrow">01 / PAYMENT DETAILS</div><div class="summary-line"><span>Tournament</span><b><?=e($r['tournament_name'])?></b></div><div class="summary-line"><span>Team</span><b><?=e($r['team_name'])?></b></div><div class="summary-line"><span>Registration ID</span><b><?=e($r['registration_code'])?></b></div><div class="price-line"><span>TOTAL DUE</span><b>₹<?=number_format((float)$r['amount'],2)?></b></div><div class="eyebrow mt-4">02 / SCAN QR PREVIEW</div><div class="qr-area"><div id="qr" data-value="<?=e($upi)?>"></div><b>AMOUNT · ₹<?=number_format((float)$r['amount'],2)?></b></div><div class="notice"><b>Payment note:</b> the QR is addressed to your configured UPI ID and includes this registration’s exact amount. Please confirm the payee and amount in your UPI app before authorizing. QR generation itself does not verify receipt; submitted references still require administrator review.</div><div class="eyebrow mt-4">03 / SUBMIT FOR REVIEW</div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=$id?>"><label>Transaction reference / UTR<input name="reference" required minlength="6" maxlength="100" placeholder="Demo reference"></label><button class="btn btn-hot btn-lg w-100">Submit for verification ↗</button></form></section><aside class="box"><div class="eyebrow">PAYMENT STATUS</div><h2><?=e(str_replace('_',' ',$r['pay_status']))?></h2><p class="muted">Your entry is confirmed only after the administrator verifies the submitted payment reference. A real payment gateway is not configured in this local demo.</p><a class="text-link" href="dashboard.php">Back to My Arena ↗</a></aside></div><?php require 'includes/footer.php';?>
